VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,7.15,"Lecture seven. Swarm intelligence. This is how many simple ants can find short routes together."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":20.016,"caps":[[0.5,5.31,"A colony is many identical, simple ants."],[5.56,8.61,"Each one only reacts to what is near it."],[8.86,13.03,"No leader gives the orders."],[13.28,19.45,"Together they can find short routes."]],"warp":[[0,0],[0.5,0.4],[5.56,3],[8.86,6.4],[13.28,8.3],[20.016,10.8]]},{"dur":18.343,"caps":[[0.5,4.11,"One scout ant is right 60% of the time."],[4.36,9.49,"Eleven scouts each vote for a route."],[9.74,13.27,"The majority is right 75% of the time."],[13.52,17.45,"With 31 scouts it climbs to 87%."]],"warp":[[0,0],[0.5,0.4],[4.36,3],[9.74,5.8],[13.52,8.9],[18.343,11.6]]},{"dur":25.101,"caps":[[0.5,6.03,"Ants use either of two equal bridges."],[6.28,9.41,"At first the ants choose at random."],[9.66,13.91,"Ants leave pheromone and prefer strong trails."],[14.16,17.13,"Soon most ants use one bridge."],[17.38,22.99,"Which one is down to chance."]],"warp":[[0,0],[0.5,0.4],[6.28,3],[9.66,5.8],[14.16,8.8],[17.38,10.8],[25.101,13]]},{"dur":28.445,"caps":[[0.5,4.99,"One road is twice as long."],[5.24,9.81,"Same speed: the short trip ends first."],[10.06,14.47,"More pheromone, so more ants pick it."],[14.72,17.77,"Soon most ants take the short road."],[18.02,22.75,"85% of 200 colonies pick the short road."],[23,27.09,"A few lock onto the long road."]],"warp":[[0,0],[0.5,0.4],[5.24,2.9],[10.06,5.3],[14.72,7.6],[18.02,10.4],[23,12.9],[28.445,15.1]]},{"dur":24.775,"caps":[[0.5,4.99,"An ant leaves a scent mark on the ground."],[5.24,8.29,"A later ant senses it and follows."],[8.54,13.11,"That is stigmergy."],[13.36,17.85,"Scent is a sign, not the work."],[18.1,23.95,"The work itself can prompt others."]],"warp":[[0,0],[0.5,0.8],[5.24,3.4],[8.54,5.6],[13.36,8],[18.1,9.9],[24.775,12.3]]},{"dur":28.329,"caps":[[0.77,5.02,"Each step, ants add pheromone."],[5.27,8.72,"Each step, a fifth of it evaporates."],[8.97,15.86,"It levels off where gain equals loss."],[16.11,23.64,"Stronger trails get picked more."],[23.89,27.26,"If the ants stop, the trail fades away."]],"warp":[[0,0],[0.77,1.4],[5.27,3.6],[8.97,6.4],[16.11,8.9],[23.89,11.1],[28.329,14.1]]},{"dur":36.664,"caps":[[0.55,6.64,"Goal: visit every town, then go home."],[6.89,12.9,"Weight = pheromone ÷ distance."],[13.15,19.08,"A random pick, by those chances."],[19.33,23.26,"Tour memory stops repeat visits."],[23.51,28.8,"It visits every town, then goes home."],[29.05,34.58,"Tour length: 4 + 6 + 3 + 5 = 18."]],"warp":[[0,0],[0.55,1],[6.89,3.3],[13.15,5.4],[19.33,8.3],[23.51,11],[29.05,13.3],[36.664,15.5]]},{"dur":25.008,"caps":[[0.5,5.31,"Tour done. Now the trails update."],[5.56,11.73,"In this example, each road keeps half."],[11.98,19.67,"Then each tour road gains Q ÷ length."],[19.92,23.53,"Skipped roads only lose pheromone."]],"warp":[[0,0],[0.5,0.5],[5.56,2.6],[11.98,5.2],[19.92,7.7],[25.008,11]]},{"dur":27.074,"caps":[[0.99,7,"Ants go round one after another."],[7.25,14.38,"A shorter tour adds more to each road."],[14.63,20.32,"So the trail leans towards the shortest tour."],[20.57,26.1,"The first ants found only long tours."]],"warp":[[0,0],[0.99,1.8],[7.25,3.8],[14.63,6.6],[20.57,10.1],[27.074,12.8]]},{"dur":13.329,"caps":[],"warp":[[0,0],[0.5,0.9],[4.44,2],[8.54,3.1],[13.329,9]]}]};
